    s.c_str()
  );

  statusCharacteristic->notify();
}

// ------------------------------------------------------------
// BLE COMMAND PROCESSOR
// ------------------------------------------------------------

void touchAudio(){
  lastAudioPacket=millis();
}

void processSingleCommand(String command){
  command.trim();
  if(!command.length())return;

  int split=command.indexOf('=');

  String key=
    (split>=0) ?
    command.substring(0,split) :
    command;

  String value=
    (split>=0) ?
    command.substring(split+1) :
    "";

  key.trim();
  value.trim();
  key.toUpperCase();

  if(key=="FX")
    setEffect(value);

  else if(key=="BG")
    backgroundColor=hexToColor(value);

  else if(key=="FG")
    foregroundColor=hexToColor(value);

  else if(key=="MAIN" ||
          key=="ACC")
    mainColor=hexToColor(value);

  else if(key=="BRI"){
    brightness=(uint8_t)constrain(
      value.toInt(),
      0,255
    );

    FastLED.setBrightness(
      brightness
    );
  }

  else if(key=="SPD")
    effectSpeed=(uint8_t)constrain(
      value.toInt(),
      1,255
    );

  else if(key=="INT")
    effectIntensity=(uint8_t)constrain(
      value.toInt(),
      1,255
    );

  else if(key=="SIZE")
    effectSize=(uint8_t)constrain(
      value.toInt(),
      1,255
    );

  else if(key=="DENS" ||
          key=="DENSITY")
    effectDensity=(uint8_t)constrain(
      value.toInt(),
      1,255
    );

  else if(key=="TRAIL" ||
          key=="FADE")
    effectTrail=(uint8_t)constrain(
      value.toInt(),
      1,255
    );

  else if(key=="DIR"){
    String v=value;
    v.toUpperCase();

    directionForward=
      !(v=="REV" ||
        v=="REVERSE" ||
        v=="-1" ||
        v=="0");
  }

  else if(key=="MIRROR")
    mirrorMode=
      value.toInt()>0;

  else if(key=="ORDER")
    setOrder(value);

  else if(key=="AUDIO")
    audioEnabled=
      value.toInt()>0;

  else if(key=="AUDMODE")
    setAudioMode(value);

  else if(key=="AUDAMT")
    audioAmount=(uint8_t)constrain(
      value.toInt(),
      0,255
    );

  else if(key=="LEVEL"){
    audioLevel=(uint8_t)constrain(
      value.toInt(),
      0,255
    );
    touchAudio();
  }

  else if(key=="BASS"){
    audioBass=(uint8_t)constrain(
      value.toInt(),
      0,255
    );
    touchAudio();
  }

  else if(key=="MID"){
    audioMid=(uint8_t)constrain(
      value.toInt(),
      0,255
    );
    touchAudio();
  }

  else if(key=="HIGH"){
    audioHigh=(uint8_t)constrain(
      value.toInt(),
      0,255
    );
    touchAudio();
  }

  else if(key=="BEAT"){
    if(value.toInt()>0)
      lastBeatAt=millis();

    touchAudio();
  }

  else if(key=="LEDS"){
    long n=value.toInt();

    if(n<1)n=1;
    if(n>MAX_LEDS)n=MAX_LEDS;

    ledCount=(uint16_t)n;
    activeLedCount=ledCount;

    clearUnused();
  }

  else if(key=="PIN"){
    long p=value.toInt();

    if(p<0)p=0;
    if(p>39)p=39;

    dataPin=(uint8_t)p;
  }

  else if(key=="SAVE")
    saveSettings();

  else if(key=="STATUS")
    sendStatus();

  else if(key=="REBOOT"){
    saveSettings();
    delay(100);
    ESP.restart();
  }
}

void processCommand(String input){
  int start=0;

  while(start<input.length()){
    int end=input.indexOf(
      ';',
      start
    );

    if(end<0)
      end=input.length();

    processSingleCommand(
      input.substring(start,end)
    );

    start=end+1;
  }

  sendStatus();
}

