    );

  if(millis()-lastFlash>=period){
    lastFlash=millis();
    flashPhase^=1;
  }

  fill_solid(
    leds,
    activeLedCount,
    flashPhase ?
    mainColor :
    backgroundColor
  );
}

void effectDualFlash(){
  uint16_t period=
    (uint16_t)map(
      reactiveSpeed(),
      1,255,
      1000,180
    );

  uint16_t t=
    millis()%period;

  CRGB c=
    backgroundColor;

  if(t<period/10)
    c=foregroundColor;

  else if(t<period/5)
    c=backgroundColor;

  else if(t<period*3/10)
    c=mainColor;

  fill_solid(
    leds,
    activeLedCount,
    c
  );
}

void effectVU(){
  fill_solid(
    leds,
    activeLedCount,
    backgroundColor
  );

  uint16_t lit=
    (uint16_t)map(
      audioLevel,
      0,255,
      0,activeLedCount
    );

  for(uint16_t i=0;
      i<lit;
      i++){

    uint8_t a=
      (uint8_t)map(
        i,
        0,
        activeLedCount>1 ?
        activeLedCount-1 :
        1,
        0,255
      );

    putPixel(
      i,
      mixColor(
        foregroundColor,
        mainColor,
        a
      )
    );
  }
}

void effectSpectrum(){
  fill_solid(
    leds,
    activeLedCount,
    backgroundColor
  );

  uint16_t third=
    activeLedCount/3;

  if(third<1)
    third=1;

  uint16_t b=
    (uint16_t)map(
      audioBass,
      0,255,
      0,third
    );

  uint16_t m=
    (uint16_t)map(
      audioMid,
      0,255,
      0,third
    );

  uint16_t hStart=
    third*2;

  uint16_t hSize=
    activeLedCount>hStart ?
    activeLedCount-hStart :
    0;

  uint16_t h=
    (uint16_t)map(
      audioHigh,
      0,255,
      0,hSize
    );

  CRGB midColor=
    mixColor(
      foregroundColor,
      mainColor,
      128
    );

  for(uint16_t i=0;
      i<b &&
      i<activeLedCount;
      i++)
    putPixel(
      i,
      foregroundColor
    );

  for(uint16_t i=0;
      i<m &&
      third+i<activeLedCount;
      i++)
    putPixel(
      third+i,
      midColor
    );

  for(uint16_t i=0;
      i<h &&
      hStart+i<activeLedCount;
      i++)
    putPixel(
      hStart+i,
      mainColor
    );
}

void effectAudioPulse(){
  uint8_t level=
    audioLevel>audioBass ?
    audioLevel :
    audioBass;

  fill_solid(
    leds,
    activeLedCount,
    mixColor(
      backgroundColor,
      foregroundColor,
      level
    )
  );

  if(beatLive())
    fill_solid(
      leds,
      activeLedCount,
      mainColor
    );
}

void effectBeatFlash(){
  fill_solid(
    leds,
    activeLedCount,
    beatLive() ?
    mainColor :
    mixColor(
      backgroundColor,
      foregroundColor,
      (uint8_t)(
        audioLevel>>1
      )
    )
  );
}

// ------------------------------------------------------------
// AUDIO OVERLAY
//
// This is the important architectural difference.
// COMET can stay COMET while Spectrum/Beat/Full reacts over it.
// ------------------------------------------------------------

void applyAudioOverlay(){
  if(!audioLive())
    return;

  bool spectrum=
    audioMode==AM_SPECTRUM ||
    audioMode==AM_FULL;

  bool beat=
    audioMode==AM_BEAT ||
    audioMode==AM_FULL;

  if(spectrum &&
     currentEffect!=FX_SPECTRUM){

    uint16_t third=
      activeLedCount/3;

    if(third<1)
      third=1;

    uint16_t b=
      (uint16_t)map(
        audioBass,
        0,255,
        0,third
      );

    uint16_t m=
      (uint16_t)map(
        audioMid,
        0,255,
        0,third
      );

    uint16_t hs=
      third*2;

    uint16_t hsize=
      activeLedCount>hs ?
      activeLedCount-hs :
      0;

    uint16_t h=
      (uint16_t)map(
        audioHigh,
        0,255,
        0,hsize
      );

    uint8_t amt=
      (uint8_t)map(
        audioAmount,
        0,255,
        0,210
      );

    CRGB midColor=
      mixColor(
        foregroundColor,
        mainColor,
        128
      );

    for(uint16_t i=0;
        i<b &&
        i<activeLedCount;
        i++)
      leds[i]=
        mixColor(
          leds[i],
          foregroundColor,
          amt
        );

    for(uint16_t i=0;
        i<m &&
        third+i<activeLedCount;
        i++)
      leds[third+i]=
        mixColor(
          leds[third+i],
          midColor,
          amt
        );

    for(uint16_t i=0;
        i<h &&
        hs+i<activeLedCount;
        i++)
      leds[hs+i]=
        mixColor(
          leds[hs+i],
          mainColor,
          amt
        );
  }

  if(beat &&
     beatLive() &&
     currentEffect!=FX_BEAT_FLASH){

    uint8_t amt=
      (uint8_t)map(
        audioAmount,
        0,255,
        30,230
      );

    for(uint16_t i=0;
        i<activeLedCount;
        i++)
      leds[i]=
        mixColor(
          leds[i],
          mainColor,
          amt
        );
  }
}

