    case FX_FLOW_STRIPE:
      effectFlowStripe();
      break;

    case FX_COLOR_WAVES:
      effectColorWaves();
      break;

    case FX_SPARKLE:
      effectSparkle();
      break;

    case FX_GLITTER:
      effectGlitter();
      break;

    case FX_TWINKLE:
      effectTwinkle();
      break;

    case FX_TWINKLEFOX:
      effectTwinkleFox();
      break;

    case FX_TWINKLECAT:
      effectTwinkleCat();
      break;

    case FX_FIREWORKS:
      effectFireworks();
      break;

    case FX_RAIN:
      effectRain();
      break;

    case FX_TETRIX:
      effectTetrix();
      break;

    case FX_FIRE:
      effectFire();
      break;

    case FX_LIGHTNING:
      effectLightning();
      break;

    case FX_PACIFICA:
      effectPacifica();
      break;

    case FX_SUNRISE:
      effectSunrise();
      break;

    case FX_DANCING_SHADOWS:
      effectDancingShadows();
      break;

    case FX_PRIDE:
      effectPride();
      break;

    case FX_BREATHE:
      effectBreathe();
      break;

    case FX_FLASH:
      effectFlash();
      break;

    case FX_DUAL_FLASH:
      effectDualFlash();
      break;

    case FX_VU:
      effectVU();
