      break;

    case FX_BEAT_FLASH:
      effectBeatFlash();
      break;
  }

  applyAudioOverlay();
  showFrame();
}

// ------------------------------------------------------------
// SETUP
// ------------------------------------------------------------

void setup(){
  Serial.begin(115200);
  delay(350);

  Serial.println();
  Serial.println("======================");
  Serial.println("SHYNETYME BT V3");
  Serial.println("======================");

  loadSettings();

  bool pinOK=
    configureLEDOutput(
      activeDataPin
    );

  if(!pinOK)
    Serial.println(
      "Unsupported GPIO saved. Using GPIO 13."
    );

  FastLED.setBrightness(
    brightness
  );

  FastLED.setMaxPowerInVoltsAndMilliamps(
    5,
    2500
  );

  fill_solid(
    leds,
    MAX_LEDS,
    CRGB::Black
  );

  fill_solid(
    outputLeds,
    MAX_LEDS,
    CRGB::Black
  );

  showFrame();

  setupBluetooth();

  Serial.print("LEDs: ");
  Serial.println(activeLedCount);

  Serial.print("GPIO: ");
  Serial.println(activeDataPin);

  Serial.print("Order: ");
  Serial.println(orderName());

  Serial.println(
    "Waiting for Bluetooth controller..."
  );
}

// ------------------------------------------------------------
// MAIN LOOP
// ------------------------------------------------------------

void loop(){
  uint16_t frameInterval=
    (uint16_t)map(
      reactiveSpeed(),
      1,255,
      85,9
    );

  if(millis()-lastFrame>=frameInterval){
    lastFrame=millis();
    runEffect();
  }

  static unsigned long lastStatus=0;

  if(bluetoothConnected &&
     millis()-lastStatus>=2500){

    lastStatus=millis();
    sendStatus();
  }
}
